12			// The two owners share firstName+lastName (the namesake key) but use DIFFERENT postcodes so
13			// they never fall into the same computed household once keys householdId on
14			// (lastName, postcode) -- otherwise the later household-duplicate block would 409 the setup.
15			String first = "Ann", last = uniqueLastName();
16			ObjectNode a = ownerNode();
17			a.put("firstName", first); a.put("lastName", last); a.put("postcode", "2000");
